-- One read-only JSON result; hashes record definitions without exposing bodies/data.
BEGIN READ ONLY;
SET LOCAL statement_timeout = '30s';
SELECT jsonb_build_object(
  'database',current_database(), 'actor',current_user,
  'server_version',current_setting('server_version'),
  'backend_pid',pg_catalog.pg_backend_pid(),
  'extensions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',extname,'version',extversion) ORDER BY extname),'[]') FROM pg_catalog.pg_extension),
  'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypassrls',rolbypassrls,'login',rolcanlogin) ORDER BY rolname) FROM pg_catalog.pg_roles WHERE rolname IN ('postgres','anon','authenticated','service_role','supabase_auth_admin','supabase_storage_admin')),
  'tables',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_catalog.pg_get_userbyid(c.relowner)) ORDER BY n.nspname,c.relname),'[]') FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('public','private','auth','storage') AND c.relkind IN ('r','p')),
  'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition_md5',pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'settings',p.proconfig,'owner',pg_catalog.pg_get_userbyid(p.proowner),'execute',jsonb_build_object('anon',pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE'))) ORDER BY p.oid::regprocedure::text),'[]') FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname IN ('public','private','auth','storage') AND p.prokind IN ('f','p')),
  'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'enabled',t.tgenabled,'definition_md5',pg_catalog.md5(pg_catalog.pg_get_triggerdef(t.oid))) ORDER BY t.tgrelid::regclass::text,t.tgname),'[]') FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid = t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('public','private') AND NOT t.tgisinternal),
  'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',p.polrelid::regclass::text,'name',p.polname,'command',p.polcmd,'roles',p.polroles,'using_md5',pg_catalog.md5(pg_catalog.pg_get_expr(p.polqual,p.polrelid)),'check_md5',pg_catalog.md5(pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid))) ORDER BY p.polrelid::regclass::text,p.polname),'[]') FROM pg_catalog.pg_policy p JOIN pg_catalog.pg_class c ON c.oid = p.polrelid JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('public','private')),
  'table_grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'role',r.role_name,'select',pg_catalog.has_table_privilege(r.role_name,c.oid,'SELECT'),'insert',pg_catalog.has_table_privilege(r.role_name,c.oid,'INSERT'),'update',pg_catalog.has_table_privilege(r.role_name,c.oid,'UPDATE'),'delete',pg_catalog.has_table_privilege(r.role_name,c.oid,'DELETE')) ORDER BY c.oid::regclass::text,r.role_name),'[]') FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace CROSS JOIN (VALUES ('anon'),('authenticated'),('service_role')) AS r(role_name) WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p'))
);
COMMIT;
